      "title": "WASPとアメリカニズム",
      "body": [
        "こうして<strong class=\"source-bold\">黒人への<ruby>偏見<rt>へんけん</rt></ruby>を強めた北部</strong>の連中は、おもに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>WASP<rt>ワスプ</rt></ruby></strong></span>（“White Anglo Saxon Protestant”）、つまり<strong class=\"source-bold\">白人・イギリス系・新教徒</strong>で、自分たちの価値観が<strong class=\"source-bold\">「アメリカニズム」</strong>だと主張した。"
      ],
