      "id": "modern-c04-l15-p01-044",
      "title": "1924年の移民法とアジアからの禁止",
      "body": [
        "さらにこうした<ruby>偏見<rt>へんけん</rt></ruby>から、<strong class=\"source-bold\">移民を排除する動き</strong>も起こったよ。1924年に改正された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">移民法</strong></span>では、年間の移民数の上限を15万人としたうえで、<strong class=\"source-bold\">出身国別の割り当て数</strong>を決めたんだけど、<strong class=\"source-bold\">アジアからの移民は全面禁止</strong>になった。"
      ],
      "plainBody": [
        "さらにこうした偏見から、移民を排除する動きも起こったよ。1924年に改正された移民法では、年間の移民数の上限を15万人としたうえで、出身国別の割り当て数を決めたんだけど、アジアからの移民は全面禁止になった。"
      ],
