      "id": "modern-c04-l15-p02-001",
      "title": "1918年の選挙法改正",
      "body": [
        "大戦中に<strong class=\"source-bold\">女性労働者</strong>が工場の労働者となって<strong class=\"source-bold\">戦争に協力した</strong>から、イギリスでも大戦末期の1918年、<strong class=\"source-bold\">ロイド＝ジョージ<ruby>挙国一致<rt>きょこくいっち</rt></ruby>内閣</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第4回選挙法改正</strong></span>をおこない、<strong class=\"source-bold\">21歳以上</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">男性普通選挙</strong></span>と<strong class=\"source-bold\">30歳以上</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">女性参政権</strong></span>が実現した。"
      ],
      "plainBody": [
        "大戦中に女性労働者が工場の労働者となって戦争に協力したから、イギリスでも大戦末期の1918年、ロイド＝ジョージ挙国一致内閣が第4回選挙法改正をおこない、21歳以上の男性普通選挙と30歳以上の女性参政権が実現した。"
      ],
