      "title": "第2党の労働党が連立で政権へ",
      "body": [
        "労働者の参政権が拡大すると、議会では労働党が増えるよね。そして総選挙で保守党が過半数を取れずに<strong class=\"source-bold\">労働党が第2党</strong>になると、1924年には<strong class=\"source-bold\">自由党との連立</strong>で、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次マクドナルド労働党内閣</strong></span>が成立したよ。"
      ],
