      "title": "戦闘ファッシからファシスト党へ",
      "body": [
        "こうして<strong class=\"source-bold\">ムッソリーニは反社会主義運動を始め</strong>、ミラノで復員兵士などとともに<strong class=\"source-bold\">「戦闘ファッシ（戦士のファッシ）」</strong>を結成すると、1921年には武力集団だった戦闘ファッシを政党に変えたんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ファシスト党</strong></span> <strong class=\"source-bold\">【</strong>国民ファシスト党<strong class=\"source-bold\">】</strong>だよ。"
      ],
