      "title": "白軍との内戦と連合国の出兵",
      "body": [
        "革命後のロシア国内では、<strong class=\"source-bold\">社会主義を<ruby>潰<rt>つぶ</rt></ruby>そうとする旧ロシア帝国軍などの反革命勢力</strong>（これを<strong class=\"source-bold\">白軍</strong>って呼んでるよ）との<strong class=\"source-bold\">内戦</strong>が起きて、ソヴィエト政権を大きく揺るがし、さらに<strong class=\"source-bold\">連合国も社会主義の拡大を警戒して出兵</strong>してきたんだ。"
      ],
