      "id": "modern-c04-l15-p05-008",
      "title": "共産勢力の結集とチェカ",
      "body": [
        "これは、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア共産党</strong></span>の指導のもとに、<strong class=\"source-bold\">世界各地の共産勢力を結集</strong>するための組織だ。さらに、<strong class=\"source-bold\">国内の反革命を取り締まるための秘密警察組織</strong>（国内スパイだ！）である<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェカ</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">非常委員会</strong></span><strong class=\"source-bold\">】</strong>が設置されたよ。"
      ],
