        "それに、世界恐慌の影響を受けなかったように見えるのは、アメリカと国交のないソ連が、アメリカの不況の影響を受けなかっただけだし、強制労働が経済成長を支えていただけだからね。大恐慌に苦しむ各国が、見た目の工業発展にダマされていただけだよ。"
