      "id": "modern-c04-l15-p07-001",
      "title": "金本位制と急増した外国債",
      "body": [
        "日本は、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>金本位制<rt>きんほんいせい</rt></ruby>を採用</strong></span> ［1897］してから<strong class=\"source-bold\">外国資本の導入</strong>を進めたんだけど、<ruby>日露<rt>にちろ</rt></ruby>戦争以来、<strong class=\"source-bold\">外国債</strong>（外国からの借金）が一気に増えたんだ（1903年に1億円→1913年に17億円）。"
      ],
      "plainBody": [
        "日本は、金本位制を採用 ［1897］してから外国資本の導入を進めたんだけど、日露戦争以来、外国債（外国からの借金）が一気に増えたんだ（1903年に1億円→1913年に17億円）。"
      ],
