      "title": "返済できない震災手形が不良債権へ",
      "body": [
        "でも、震災手形の債務者（お金を借りている会社など）のなかには、すでに戦後恐慌で<ruby>潰<rt>つぶ</rt></ruby>れそうになっていた会社も含まれていて、いくら猶予したところで返済できない債務がたくさんあって、これが不良債権になってしまったんだ。"
      ],
