export const sourcePages = {
  "275": "<h2>275</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第15回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">戦間期の欧米諸国 〜世界恐慌以前〜</strong></span></h1>\n<p>今回は、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ヴェルサイユ体制下の欧米諸国</strong></u>について見ていくよ。1920年代、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ヨーロッパ各国が戦後の荒廃</strong></u>で苦しむなか、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アメリカは空前の繁栄</strong></u>を迎えていたよ！ さらに、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">革命後のロシア</strong></u>はどうなるんだろう？</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span></td><td><strong class=\"source-bold\">アメリカ合衆国の繁栄 〜黄金の20年代〜</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">276〜278ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span></td><td><strong class=\"source-bold\">大英帝国の再編とフランス</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">278〜280ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span></td><td><strong class=\"source-bold\">ドイツ 〜ヴァイマル共和国の混乱と復興〜</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">280〜283ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span></td><td><strong class=\"source-bold\">イタリア 〜ファシズム政権の出現〜</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">283〜286ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span></td><td><strong class=\"source-bold\">ソ連 〜社会主義国家の建設〜</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">286〜290ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">6</strong></span></td><td><strong class=\"source-bold\">戦間期の東欧諸国</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">290〜291ページ</span></td></tr></tbody></table></div>\n<blockquote><p>第一次世界大戦からの再建を目指す各国では、何が起きていたんだろう？</p></blockquote>\n<p><u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ヨーロッパの戦後<ruby>復興<rt>ふっこう</rt></ruby></strong></u>は、各国で状況が違っていたよ。戦勝国としてなんとかヨーロッパの国際関係をリードできた<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">イギリス</strong></u>、ドイツからの<ruby>賠償金<rt>ばいしょうきん</rt></ruby>を一番多くもらえた<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">フランス</strong></u>は、どうにか<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">再建への道筋をつけた</strong></u>。<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">賠償問題で苦しむドイツ</strong></u>もドーズ案で再建に向けて歩み始めた。しかし、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">経済基盤の弱かったイタリア</strong></u>では、すでに<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ファシズム政権</strong></u>が成立し、社会主義国<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ソ連は共産党の一党<ruby>独裁<rt>どくさい</rt></ruby></strong></u>になっちゃった。そして<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">一人勝ち状態になったのがアメリカ</strong></u>だよ。各国の特色をしっかりおさえてね。</p>\n<p>それじゃあ、戦間期の欧米諸国の始まり〜。</p>",
  "276": "<h2>276</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第15回</strong></span> 戦間期の欧米諸国 〜世界恐慌以前〜</p>\n<h2><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">アメリカ合衆国の繁栄 〜黄金の20年代〜</strong></span></h2>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">「<ruby>債務国<rt>さいむこく</rt></ruby>から<ruby>債権国<rt>さいけんこく</rt></ruby>へ」。アメリカが世界一の経済大国になった！</strong></span></h3>\n<p>第一次世界大戦後、戦争の被害を受けていないアメリカは、戦後は<strong class=\"source-bold\">世界最大の工業国・農業国</strong>となり、さらに<strong class=\"source-bold\">英仏への多額の<ruby>戦債<rt>せんさい</rt></ruby></strong>によって、戦前には<strong class=\"source-bold\">債務国</strong>（借金している国）だったのが、気づけば世界一の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">債権国</strong></span>（お金を貸してる国）となった。こうしてアメリカが金融の<ruby>覇権<rt>はけん</rt></ruby>を握り、<strong class=\"source-bold\">世界金融の中心</strong>は<strong class=\"source-bold\">ロンドン</strong>の<strong class=\"source-bold\">ロンバード街【シティ】</strong>から<strong class=\"source-bold\">ニューヨーク</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウォール街</strong></span>へと移ったんだ。</p>\n<p><strong class=\"source-bold\">民主党</strong>の大統領<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウィルソン</strong></span>は、国内では<strong class=\"source-bold\">「新しい自由」</strong>をスローガンに民主的な改革をおこない、1920年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">女性参政権</strong></span>を実現したよ。背景は、<strong class=\"source-bold\">大戦中に男性が兵士として従軍したかわりに女性が工場労働者となるなど、社会進出が進んだ</strong>ことだね。ただ外交的には、国内で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">孤立主義</strong></span>の風潮が強まり、共和党が多数派となっている<strong class=\"source-bold\">上院がヴェルサイユ条約を<ruby>批准<rt>ひじゅん</rt></ruby>しなかった</strong>から、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際連盟には不参加</strong></span>となるなど、思うような政策が実現しなかった。ていうか、<strong class=\"source-bold\">ウィルソンはあんまり人気がない</strong>。理想主義に突っ走りすぎて、国民は「いい加減、民主党じゃなくていいだろ」って思っていたんだ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">3代続いた共和党政権は自由放任主義で、空前の好景気になった！</strong></span></h3>\n<p>こうして1920年の大統領選挙では、「昔のような平穏で安定したアメリカに戻りましょう！」という主張（<strong class=\"source-bold\">“平和への復帰【<ruby>常態<rt>じょうたい</rt></ruby>への復帰】”</strong>）を掲げた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">共和党</strong></span>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハーディング</strong></span>が当選したよ。共和党は<strong class=\"source-bold\">産業資本家の利益を<ruby>代弁<rt>だいべん</rt></ruby></strong>していたから、とにかく経済界が<ruby>儲<rt>もう</rt></ruby>かる政策をとり、基本的には<strong class=\"source-bold\">「自由放任」</strong>で経済活動に政府が<ruby>介入<rt>かいにゅう</rt></ruby>せず、規制もしなかったから<strong class=\"source-bold\">大企業（独占資本）はますます発展した</strong>。しかも、法人や富裕層に対する減税をしたから、金持ちはますます金持ちになったんだ。さらに、すでに<strong class=\"source-bold\">工業生産で世界一</strong>になっているのに<strong class=\"source-bold\">高関税政策</strong>をとったんだよ。これって、「オマエらのものは買わないけど、オマエらはアメリカ製品を買えよ」って意味でしょ。ただのワガママじゃん。そして、「大企業優先」の政策のウラで、企業が共和党にワイロを贈りまくったから、<strong class=\"source-bold\"><ruby>汚職<rt>おしょく</rt></ruby>が広がった</strong>のもこの時代だ。</p>\n<p>その後、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">クーリッジ</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フーヴァー</strong></span>と続いた共和党政権も、<strong class=\"source-bold\">大企業優先の「自由放任」を続けた</strong>から、アメリカは<strong class=\"source-bold\">「黄金の20年代」</strong>といわれる空前の好景気となった。1929年に大統領になった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フーヴァー</strong></span>は、こうした状況を「アメリカ資本主義の<strong class=\"source-bold\">“永遠の繁栄”</strong>」と言っていたんだ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">アメリカ経済繁栄のキーワードは、「大量生産・大量消費」だ！</strong></span></h3>\n<p>この時期のアメリカ政治史では、<strong class=\"source-bold\">入試に出せるのは大統領の名前くらい</strong>。だって、あとは<strong class=\"source-bold\">「自由放任」</strong>って、要は「ほったらかしで何もしない」ってことでしょ。だから、経済史や社会史が問題になるよ。</p>\n<p>まずは経済史からいこう。キーワードは「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大量生産・大量消費</strong></span>」だ。その<ruby>象徴<rt>しょうちょう</rt></ruby>が</p>",
  "277": "<h2>277</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アメリカ合衆国の繁栄 〜黄金の20年代〜</u></p>\n<p><strong class=\"source-bold\">フォード自動車会社</strong>が始めた<strong class=\"source-bold\">「大量生産方式」</strong>だよ。今では当たり前なんだけど、<strong class=\"source-bold\">ベルトコンベアを使った流れ作業</strong>を導入して<strong class=\"source-bold\">自動車の量産</strong>に成功した。これまで、自動車職人が1台の車を最初から最後まで1人で組み立てたのを、「ハンドルだけ付ける人」「タイヤだけ付ける人」みたいな分業にして、<strong class=\"source-bold\">給料の安い単純労働者だけでクルマを組み立てられるようにした</strong>んだ。だから自動車の値段が下がって、大衆車<strong class=\"source-bold\">「T型フォード」</strong>が売れまくった。あまりに自動車が普及して、この時期のアメリカの若者はクルマがないとデートができなかったらしいよ……。</p>\n<p>さらに、<strong class=\"source-bold\">ラジオ</strong>や雑誌などのマスメディアの普及によって、<strong class=\"source-bold\">プロ野球</strong>（メジャーリーグ）や<strong class=\"source-bold\">映画</strong>（ハリウッドだよ！）、<strong class=\"source-bold\">ミュージカル</strong>（ブロードウェイ）、<strong class=\"source-bold\">ジャズ</strong>の流行など、現代まで続く<strong class=\"source-bold\">大衆文化</strong>が現れたよ。</p>\n<p>そして、アメリカでは<strong class=\"source-bold\">洗濯機、アイロン、冷蔵庫</strong>などの<strong class=\"source-bold\">家電製品</strong>が普及して、家事労働が楽になったから、<strong class=\"source-bold\">女性の社会進出が進んだ</strong>。例えば、洗濯板でやってた洗濯を洗濯機が勝手にやってくれるなんて驚きだ！……って「洗濯板って何？」だよね。ネットで検索してごらん。写真付きで出てくるよ。また、カタログによる<strong class=\"source-bold\">通信販売</strong>も始まり、さらに分割払いのクレジット（教科書だと<strong class=\"source-bold\">「信用販売／<ruby>月賦<rt>げっぷ</rt></ruby>」</strong>）の普及で、気軽にモノが買える<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大衆消費社会</strong></span>になった反面で、<strong class=\"source-bold\">家計の借金（ローン）が増えていた</strong>んだ。</p>\n<blockquote><p>このころにアメリカで出現した大衆消費社会が、現代の生活にも大きく影響しているんだよ</p></blockquote>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">WASP（ワスプ）が保守化して、アメリカニズムが高揚した！</strong></span></h3>\n<p>続いて社会の変化だよ。大戦中に<strong class=\"source-bold\">白人男性が兵士として従軍</strong>し、しかも大戦によって<strong class=\"source-bold\">ヨーロッパからの移民が激減</strong>したから、アメリカでは東部の工業都市を中心に<strong class=\"source-bold\">労働力不足</strong>になった。この時、アメリカでは<strong class=\"source-bold\">女性と黒人</strong>が工場労働者になったんだけど、特に<strong class=\"source-bold\">黒人が工業都市へと移住</strong>を始めたんだ。だって、労働力が足んないからむちゃくちゃ給料が高かったんだもん。当時の南部と比較すると、北部の製鉄所などでは<strong class=\"source-bold\">給料が南部の5倍以上</strong>！ そりゃ引っ越すよ。ただ、大戦後には<strong class=\"source-bold\">黒人の移住</strong>を背景に<strong class=\"source-bold\">「白人層の保守化」</strong>が起きたんだ。</p>\n<p>大戦が終わって<strong class=\"source-bold\">戦地から帰ってきた白人たち</strong>は、突然増えた黒人に対する<strong class=\"source-bold\">拒絶反応を起こした</strong>。彼らは、まさか自分たちの近くに黒人が住むなんて思ってなかったからね。こうして<strong class=\"source-bold\">黒人への<ruby>偏見<rt>へんけん</rt></ruby>を強めた北部</strong>の連中は、おもに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>WASP<rt>ワスプ</rt></ruby></strong></span>（“White Anglo Saxon Protestant”）、つまり<strong class=\"source-bold\">白人・イギリス系・新教徒</strong>で、自分たちの価値観が<strong class=\"source-bold\">「アメリカニズム」</strong>だと主張した。要は「WASPがアメリカ人だぁ〜」ってことね。そして、<strong class=\"source-bold\">WASP以外の人びとを差別し</strong>、第一次世界大戦直後には、北部の都市の白人による<strong class=\"source-bold\">反黒人の暴動</strong>なども起こったんだ。</p>\n<p>例えば、1920年代には<strong class=\"source-bold\">反黒人組織</strong>だった<strong class=\"source-bold\">K・K・K【クー＝クラックス＝クラン】</strong>が復活して約400万人もの会員を集め、<strong class=\"source-bold\">反黒人、反ユダヤ、反カトリック、反共産主</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "278": "<h2>278</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第15回</strong></span> 戦間期の欧米諸国 〜世界恐慌以前〜</p>\n<p><strong class=\"source-bold\">義（反共）、反移民</strong>を主張して、黒人や移民などを襲撃した。また、保守化した<ruby>WASP<rt>ワスプ</rt></ruby>の連中が強要する<strong class=\"source-bold\">プロテスタント的な道徳</strong>（とにかくマジメ）から、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">禁酒法</strong></span>ができたんだ。でも、酒を飲みたい人は飲むよね……。だから、医者が「この人はウィスキーを飲まないと死にます」みたいな<ruby>処方箋<rt>しょほうせん</rt></ruby>を書いて、薬局でお酒を売ったんだって……。結局、<strong class=\"source-bold\">マフィアが密造酒でボロ<ruby>儲<rt>もう</rt></ruby>けした</strong>んだけどね。</p>\n<p>そして、全世界に大きな反響を巻き起こしたのが<strong class=\"source-bold\">サッコ・ヴァンゼッティ事件</strong>だ。これは、強盗殺人事件の容疑者として労働者のサッコと<ruby>行商人<rt>ぎょうしょうにん</rt></ruby>のヴァンゼッティが逮捕されて、<strong class=\"source-bold\">明確な証拠がないまま死刑となった</strong>という事件だよ。でも、なんで証拠がないのに死刑になったかっていうと、彼らが<strong class=\"source-bold\">イタリア系移民でアナーキスト</strong>だったから、「反移民・反共産主義」の意識が強い<ruby>陪審員<rt>ばいしんいん</rt></ruby>が「んなもん、有罪に決まってる！」って言ったからだよ。そしたら、世界中で「アメリカは何考えてるんだ〜！」って<strong class=\"source-bold\">反対する世論が盛り上がった</strong>んだけど、こんな事件が起きるくらい、<strong class=\"source-bold\">アメリカの白人層が保守化していた</strong>ってことだよ。</p>\n<p>さらにこうした<ruby>偏見<rt>へんけん</rt></ruby>から、<strong class=\"source-bold\">移民を排除する動き</strong>も起こったよ。1924年に改正された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">移民法</strong></span>では、年間の移民数の上限を15万人としたうえで、<strong class=\"source-bold\">出身国別の割り当て数</strong>を決めたんだけど、<strong class=\"source-bold\">アジアからの移民は全面禁止</strong>になった。さらに、日本人に<ruby>帰化権<rt>きかけん</rt></ruby>が認められなかったり、カリフォルニア州では日本人の土地所有を禁じられたりと、さまざまな<strong class=\"source-bold\">日系移民への差別がおこなわれた</strong>んだ。一方で、教科書には書いてないけど、ラテンアメリカからの移民は制限されなかったから、以後<strong class=\"source-bold\">メキシコ</strong>などを中心とする中南米からの移民が、増加したよ。彼らはスペイン語を話すから<strong class=\"source-bold\">「ヒスパニック」</strong>と呼ばれているね。</p>\n<blockquote><p>先住民（ネイティヴ・アメリカン）以外は全員移民のはずなのに、アメリカではWASP以外の移民が差別されたんだ</p></blockquote>\n<h2><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">大英帝国の再編とフランス</strong></span></h2>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈イギリス〉</strong></span></h3>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">選挙権が拡大して、労働党が躍進。初の労働党政権が誕生した！</strong></span></h3>\n<p>大戦中に<strong class=\"source-bold\">女性労働者</strong>が工場の労働者となって<strong class=\"source-bold\">戦争に協力した</strong>から、イギリスでも大戦末期の1918年、<strong class=\"source-bold\">ロイド＝ジョージ<ruby>挙国一致<rt>きょこくいっち</rt></ruby>内閣</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第4回選挙法改正</strong></span>をおこない、<strong class=\"source-bold\">21歳以上</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">男性普通選挙</strong></span>と<strong class=\"source-bold\">30歳以上</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">女性参政権</strong></span>が実現した。男性と女性の年齢制限が違うから、<strong class=\"source-bold\">男女普通選挙とは言わない</strong>よ！（選挙法改正一覧は<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➡P.47</strong></span>）</p>\n<p>労働者の参政権が拡大すると、議会では労働党が増えるよね。そして総選挙で保守党が過半数を取れずに<strong class=\"source-bold\">労働党が第2党</strong>になると、1924年には<strong class=\"source-bold\">自由党との連立</strong>で、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次マクドナルド労働党内閣</strong></span>が成立したよ。これが<strong class=\"source-bold\">イギリス初の労働党政権</strong>だ。<strong class=\"source-bold\">労働党は第2党</strong>だから正誤問題では気をつけよう！ こうして誕生した労働党政権</p>",
  "279": "<h2>279</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">大英帝国の再編とフランス</u></p>\n<p>だったけど、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連を承認</strong></span>したくらいしか独自の政策は打ち出せなかったんだ。そして、「労働党が革命をやろうとしている！」っていうニセ情報をめぐる事件で、わずか10カ月で倒れちゃった。次の選挙では保守党が圧勝してボールドウィン内閣ができたんだけど、これ以後「<strong class=\"source-bold\">改革の政党は労働党、保守派は保守党</strong>」というイメージが定着して、イギリスは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">保守党</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">労働党</strong></span>の<strong class=\"source-bold\">二大政党</strong>の時代になったよ。ちなみに、自由党は改革のイメージがなくなり、勢力を失っていったんだ。</p>\n<p>そして1928年、保守党の<strong class=\"source-bold\">ボールドウィン内閣</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第5回選挙法改正</strong></span>をおこなって、<strong class=\"source-bold\">21歳以上</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">男女普通選挙</strong></span>を実現し、イギリスでは<strong class=\"source-bold\">男女平等の参政権</strong>が実現したよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">大英帝国の<ruby>凋落<rt>ちょうらく</rt></ruby>……経済の中心はアメリカに移った</strong></span></h3>\n<p>大戦後のイギリスは、国際金融センターの地位をアメリカに奪われ、<strong class=\"source-bold\">世界金融の中心</strong>が<strong class=\"source-bold\">ロンドン</strong>の<strong class=\"source-bold\">ロンバード街</strong>から<strong class=\"source-bold\">ニューヨーク</strong>の<strong class=\"source-bold\">ウォール街</strong>に移ったよね。この時期のイギリスは、戦後の<ruby>復興<rt>ふっこう</rt></ruby>だけじゃなく、炭鉱労働者のゼネストなどで混乱し、<strong class=\"source-bold\">経済的な地位の低下は止まらなかった</strong>んだ。</p>\n<p>こうしてイギリスの地位が低下するとともに、<strong class=\"source-bold\">アイルランドの独立運動</strong>や<strong class=\"source-bold\">インドの民族運動</strong>が激化したよ。<strong class=\"source-bold\">アイルランド問題については</strong><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第2回</strong></span> <span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\"><strong class=\"source-bold\">➡P.50〜51</strong></span>ですでに話したけど、ほかの自治領でも、「大戦に参加して戦ったのに、もう本国の言いなりはイヤだ！」っていう声が出始めた。イギリスはなんとか植民地をつなぎとめるため、1926年<strong class=\"source-bold\">イギリス帝国会議</strong>を開いたんだ。そして<strong class=\"source-bold\">「本国と自治領を平等とするイギリス連邦」</strong>の構想を打ち出した（バルフォア報告）。この構想が法律となったのが、1931年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウェストミンスター憲章</strong></span>だよ。こうして自治領は<strong class=\"source-bold\">独自の内政権・外交権を獲得</strong>して事実上独立し、本国と自治領が<strong class=\"source-bold\">「<ruby>王冠<rt>おうかん</rt></ruby>への忠誠」</strong>によってゆるやかに結びつく<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イギリス連邦</strong></span>が発足したよ。そして、今でもイギリス連邦は残っている。例えば、国旗のなかにユニオンジャックの入っているオーストラリアやニュージーランドは、現在でもイギリス連邦内にいるよ。これ、イギリスの<ruby>恐慌<rt>きょうこう</rt></ruby>対策のところでも重要だから、しっかり頭に入れておいてね。</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">〈フランス〉</strong></span></h3>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">大戦の被害が一番ひどかったフランスは、ドイツへの強硬路線！</strong></span></h3>\n<p>第一次世界大戦で一番被害がひどかったのは、<strong class=\"source-bold\">国土の多くが戦場になったフランス</strong>だよ。しかも、ロシア革命が起きたせいで、ロシアに貸していたお金（<ruby>外債<rt>がいさい</rt></ruby>）が回収できなくなったんだ。こりゃ、復興するにもお金がないよ……。</p>\n<p>そこで<strong class=\"source-bold\">戦後復興の資金を確保</strong>するために、また<strong class=\"source-bold\">ドイツを再び強国にしない</strong>ために、ドイツに膨大な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>賠償金<rt>ばいしょうきん</rt></ruby></strong></span>を払わせたよね。実際、賠償金を一番多くもらったのはフランスだ。さらに外交的には<strong class=\"source-bold\">ドイツ包囲網をつくるため</strong>に、ベルギー、ポーランド、さらにドイツを挟み撃ちするため、露仏同盟のかわりにチェコスロヴァキア、ルーマニア、ユーゴスラヴィアがつくった小協商を支援して、のちに同盟を結んだよ。</p>\n<p>そして、もっとも強硬な政策が、<strong class=\"source-bold\">保守党のポワンカレ右派内閣</strong>がおこなった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ルー</strong></span></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "280": "<h2>280</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第15回</strong></span> 戦間期の欧米諸国 〜世界恐慌以前〜</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ル<ruby>占領<rt>せんりょう</rt></ruby></strong></span>だよ。ただ、ルール占領は<strong class=\"source-bold\">ドイツの消極的抵抗で大した成果を上げられず</strong>、国内の批判が大きくなっただけじゃなく、イギリスなどから「フランスのせいでドイツが<ruby>破綻<rt>はたん</rt></ruby>して、余計に<ruby>賠償金<rt>ばいしょうきん</rt></ruby>の支払いが遅れてるじゃないか」と文句を言われた。結果、<strong class=\"source-bold\">国内外から批判されて</strong>総選挙で負けてしまったんだよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">1920年代後半のフランス……実はアメリカに次いで世界2位の繁栄！</strong></span></h3>\n<p>こうして、1924年には<strong class=\"source-bold\">社会党と急進社会党</strong>が連合して選挙に勝利し、<strong class=\"source-bold\">左派連合政権</strong>ができたよ。外相となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブリアン</strong></span>は<strong class=\"source-bold\">平和外交を推進</strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連の承認</strong></span>、<strong class=\"source-bold\">ルールからの撤兵</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロカルノ条約</strong></span>の<ruby>締結<rt>ていけつ</rt></ruby>などの成果を上げたんだ。しかし、フランス経済を苦しめる財政難とインフレへの対策ができなかったので、政権は崩壊しちゃった。</p>\n<blockquote><p>ブリアンの平和外交は、世界を安定させたよ。しかも、何気に経済も調子よくなってる</p></blockquote>\n<p>そして再び<strong class=\"source-bold\">保守党のポワンカレ</strong>が政権に<ruby>就<rt>つ</rt></ruby>くと、<strong class=\"source-bold\">社会党と共産党以外</strong>がすべて協力する<strong class=\"source-bold\"><ruby>挙国一致<rt>きょこくいっち</rt></ruby>内閣</strong>を成立させ、<strong class=\"source-bold\">フランの切り下げ</strong>など大胆な経済政策で輸出の拡大を狙い、<strong class=\"source-bold\">重化学工業の育成</strong>にも成功したよ。例えば、自動車産業（ルノーとかプジョーとか知ってる？ 入試には出ないけど）や化学工業が発展したのはこの時期だ。さらに<strong class=\"source-bold\">アルザス・ロレーヌ</strong>の<strong class=\"source-bold\">天然資源</strong>（石炭や鉄鉱石）を背景に、<strong class=\"source-bold\">鉄鋼生産は世界3位</strong>になったんだよ。あんまりイメージないかもしれないけど、1920年代後半にフランスはアメリカに次いで繁栄し、金保有量も世界2位になったんだよ（もちろん1位はアメリカだけどね）。</p>\n<h2><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ドイツ 〜ヴァイマル共和国の混乱と復興〜</strong></span></h2>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">大戦中に社会民主党が分裂。スパルタクス団が革命を起こした！</strong></span></h3>\n<p>大戦前に<strong class=\"source-bold\">最大の反戦勢力だったはずの社会主義勢力</strong>は、大戦<ruby>勃発<rt>ぼっぱつ</rt></ruby>直前に各国の社会主義政党が「自分の国の戦争は自衛戦争だから正しい」って言い出したから、<strong class=\"source-bold\">第2インターナショナルが崩壊</strong>したよ。第2インターナショナルの中心だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ社会民主党</strong></span>も、ヴィルヘルム2世が戦争に向かうのに反対せずに、挙国一致で戦争を支える体制（「城内平和」）ができた。そしたら党内で「戦争反対〜」って言ってる連中が分裂しちゃった！。</p>\n<p>まず、<strong class=\"source-bold\">社会民主党にそのまま残った</strong>連中は、基本的に「<strong class=\"source-bold\">革命はやらず</strong>（<strong class=\"source-bold\">修正主義</strong>）」「<strong class=\"source-bold\">戦争容認</strong>」だから、これに反対するヤツらが分裂したんだよ。まず、「<strong class=\"source-bold\">革命はやらないでいい</strong>」けど「<strong class=\"source-bold\">戦争反対</strong>」なのが、<strong class=\"source-bold\">独立社会民主党</strong>だよ。ただ、彼らは少数派だったから、大戦後にはなくなっちゃった。そして、「<strong class=\"source-bold\">革命を目標にして</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルクス主義</strong></span>）」「<strong class=\"source-bold\">戦争に反対</strong>」の連中は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スパルタクス団</strong></span>をつくった。これが、のちの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ共産党</strong></span>になるよ。</p>",
  "281": "<h2>281</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ドイツ 〜ヴァイマル共和国の混乱と復興〜</u></p>\n<h3><strong class=\"source-bold\">〈社会民主党の分裂〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td><span data-source-border=\"black\" style=\"border:1px solid #222222;padding:0 0.2em\"><strong class=\"source-bold\">修正主義</strong></span></td><td><span data-source-border=\"black\" style=\"border:1px solid #222222;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルクス主義</strong></span></span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #222222;padding:0 0.2em\"><strong class=\"source-bold\">戦争容認</strong></span></td><td><strong class=\"source-bold\">社会民主党</strong></td><td>該当なし</td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #222222;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦争反対</strong></span></span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">独立社会民主党</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スパルタクス団</strong></span></td></tr></tbody></table></div>\n<blockquote><p>言葉だと複雑になるから、図で理解しよう！</p></blockquote>\n<p>そして1918年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キール軍港の水兵反乱</strong></span>をきっかけとする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ革命</strong></span>で<strong class=\"source-bold\">ヴィルヘルム2世が退位</strong>すると、<strong class=\"source-bold\">ドイツは共和国となり</strong>、社会民主党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エーベルト</strong></span>を中心とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">臨時政府</strong></span>が成立した。そして、革命の際に結成された労働者と兵士による評議会の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーテ</strong></span><strong class=\"source-bold\">【</strong>労兵レーテ<strong class=\"source-bold\">】</strong>も<strong class=\"source-bold\">議会制民主主義</strong>を支持したから、1919年に議会の選挙がおこなわれることになったんだ。</p>\n<p>しかし、社会主義革命を起こしたかった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スパルタクス団</strong></span>（正確には、1918年末に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ共産党</strong></span>になったよ）は、1919年1月にベルリンをはじめ、<strong class=\"source-bold\">各地の都市で武装<ruby>蜂起<rt>ほうき</rt></ruby></strong>したんだ。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スパルタクス団の蜂起</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ共産党の一月蜂起</strong></span>／ベルリン蜂起<strong class=\"source-bold\">】</strong>は、<strong class=\"source-bold\">旧ドイツ帝国の軍部と組んだ臨時政府が<ruby>鎮圧<rt>ちんあつ</rt></ruby></strong>し、指導者だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カール＝リープクネヒト</strong></span>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローザ＝ルクセンブルク</strong></span>は右翼将校に虐殺された！。そして、社会民主党は軍部・経済界と組んで、革命が進むことを抑え込んだんだ。</p>\n<h3><span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">世界でもっとも民主的なワイマール憲法ができたけど……</strong></span></h3>\n<p>1919年、革命勢力がまだ残っているベルリンではなく、中部ドイツの古都<strong class=\"source-bold\">ヴァイマルに国民議会が招集</strong>され、正式に社会民主党の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エーベルト</strong></span>が大統領となった。そして8月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴァイマル憲法</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ワイマール憲法</strong></span><strong class=\"source-bold\">】</strong>が制定されたよ。ここから<strong class=\"source-bold\">ナチス政権が成立するまで</strong>のドイツ共和国を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴァイマル共和国</strong></span>と呼んでいるんだ。</p>\n<blockquote><p>ヴァイマル憲法は当時の世界では一番民主的だ！ だって社会主義の社会民主党が中心になってつくったんだもん</p></blockquote>\n<p><strong class=\"source-bold\">ヴァイマル憲法は社会民主党が主導して制定</strong>されたこともあって、<strong class=\"source-bold\">当時世界でもっとも民主的な憲法</strong>となったんだ。<strong class=\"source-bold\">主権在民</strong>がうたわれ、<strong class=\"source-bold\">20歳以上</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">男女平等普通選挙</strong></span>を採用すると、民意を正確に反映するように<strong class=\"source-bold\">比例代表選挙</strong>となった。さらに、国民の基本権として、人間らしく生きる権利（<strong class=\"source-bold\">生存権</strong>）や<strong class=\"source-bold\">労働者の団結権・団体</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "282": "<h2>282</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第15回</strong></span> 戦間期の欧米諸国 〜世界恐慌以前〜</p>\n<p><strong class=\"source-bold\">交渉権</strong>などの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会権</strong></span>も認められたよ。これって、「すごくいい憲法ができたね」って思うかもしれないけど、問題がないわけじゃないんだ。</p>\n<p><strong class=\"source-bold\">大統領は国民の直接選挙で選ばれる</strong>んだけど、もともとの<strong class=\"source-bold\">「皇帝」にかわる地位</strong>だから、国家の非常事態には<strong class=\"source-bold\">議会を通さず</strong>に法律をつくったり変えたりできる<strong class=\"source-bold\">大統領非常大権【大統領緊急令】</strong>が認められた。これ、非常事態がどんな時か？っていうことがはっきりしていないから、大統領がいつでも「非常事態！」って決めちゃっていいんだよ！。<strong class=\"source-bold\">下手したら<ruby>独裁<rt>どくさい</rt></ruby>者が出てきちゃう</strong>よね。でも、エーベルトはそんなことはしない人だったから、憲法ができた時には問題なかったんだけどさ。これって、大統領になった人の思想や性格でどうにでもなっちゃうよ。</p>\n<h3><strong class=\"source-bold\">〈ヴァイマル憲法の特徴〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td>民主的な点</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">主権在民、20歳以上</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">男女平等普通選挙</strong></span><br><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">生存権</strong>の承認<br><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">労働者の団結権</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">団体交渉権</strong></span>など<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会権</strong></span>を承認</td></tr><tr><td>問題点</td><td><span data-source-color=\"green\" style=\"color:#315837\">●</span> <strong class=\"source-bold\">大統領非常大権【大統領緊急令】</strong>……独裁者が出現する可能性</td></tr></tbody></table></div>\n<p>そして、社会民主党政権に反発する軍部などの<strong class=\"source-bold\">保守派の巻き返し</strong>もあったよ。例えば、1920年に<strong class=\"source-bold\">右派政治家によるクーデタ</strong>（カップ<ruby>一揆<rt>いっき</rt></ruby>）を労働者が倒す事件が起こり、国内では「もっと民主化しろ〜」って声が高まったんだけど、逆に政権は保守化してしまった。この時期のドイツは<strong class=\"source-bold\">政権が非常に不安定だった</strong>んだ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ルール<ruby>占領<rt>せんりょう</rt></ruby>のあと、ドイツは協調外交で<ruby>復興<rt>ふっこう</rt></ruby>に向かった！</strong></span></h3>\n<p>1923年、<strong class=\"source-bold\">ルール占領でドイツ経済は<ruby>破綻<rt>はたん</rt></ruby></strong>し、国内は大きく混乱したよね。この混乱のなかで登場するのが、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヒトラー</strong></span>の率いる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナチ党</strong></span><strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国民社会主義ドイツ労働者党</strong></span><strong class=\"source-bold\">】</strong>だ（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ナチス</strong></span>とは、ナチ党のメンバーを指す呼び名）。もともとはミュンヘンで創設された小さな政治団体だったものが、ヒトラーが党首になると過激な<strong class=\"source-bold\">ヴェルサイユ条約批判</strong>や<strong class=\"source-bold\">共和国批判</strong>をおこなって、混乱したドイツのなかで勢力を拡大していったんだ。</p>\n<p>1923年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヒトラー</strong></span>は保守派を中心とする軍部クーデタのきっかけをつくるために、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ミュンヘン一揆</strong></span>を起こしたんだけど、実際には<strong class=\"source-bold\">軍部クーデタが起こらずに失敗</strong>して逮捕され、禁固刑になった。ただ、わずか8カ月で釈放されたから、この間にヒトラーは獄中で<strong class=\"source-bold\">『わが闘争』</strong>を口述筆記で書き上げ、以後、<strong class=\"source-bold\">選挙で議席を増やして政権を狙う「合法路線」に転換</strong>したんだ。</p>\n<p>こうした動きもあったけど、1923年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シュトレーゼマン</strong></span>首相が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レンテンマルク</strong></span>を発行して<strong class=\"source-bold\">インフレーションを収束</strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドーズ案</strong></span>によってフランス・ベルギー軍がルールから撤退すると、<strong class=\"source-bold\">経済の復興とともに国内も安定し始めた</strong>よ。さらに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロカルノ条約</strong></span>が結ばれて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国際連盟への加盟</strong></span>を実現するなど、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">協調外交</strong></span>によってドイツは</p>",
  "283": "<h2>283</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">イタリア 〜ファシズム政権の出現〜</u></p>\n<p>国際社会に復帰したよ。これはドイツ経済の復興にもつながり、1926年ごろには<strong class=\"source-bold\">工業生産が第一次世界大戦前の水準まで回復</strong>したんだ。だから、この時期のナチ党は「ただの危険な<ruby>右翼<rt>うよく</rt></ruby>団体」と思われて、人気のない弱小政党の一つだったよ。</p>\n<h2><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">イタリア 〜ファシズム政権の出現〜</strong></span></h2>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">クローズアップ</span> <strong class=\"source-bold\">イタリアのファシズム政権</strong></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北イタリアのストライキ</strong></span> ［1920］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span>自由主義勢力が、社会主義を警戒</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムッソリーニ</strong></span>の台頭</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> もと社会党員だったが除名され、反社会主義運動を展開</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ファシスト党</strong></span><strong class=\"source-bold\">【</strong>国民ファシスト党<strong class=\"source-bold\">】</strong>結成［1921］……<strong class=\"source-bold\">反社会主義</strong>を唱える</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローマ<ruby>進軍<rt>しんぐん</rt></ruby></strong></span>［1922］……国王が<ruby>鎮圧<rt>ちんあつ</rt></ruby>を拒否し、<strong class=\"source-bold\">ムッソリーニ政権が成立</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> ムッソリーニの国内政策</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">一党独裁体制</strong></span>を樹立 ［1926］ ……議会で他の政党を解散させて確立</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">ファシズム大評議会</strong>を<strong class=\"source-bold\">国家の最高議決機関</strong>とする ［1928］</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> ムッソリーニの対外政策</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フィウメ<ruby>併合<rt>へいごう</rt></ruby></strong></span> ［1924］ ……ユーゴスラヴィアを<ruby>恐喝<rt>きょうかつ</rt></ruby>して併合</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルバニア保護国化</strong></span> <strong class=\"source-bold\">【ティラナ条約】</strong> ［1926］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラテラノ条約</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラテラン条約</strong></span><strong class=\"source-bold\">】</strong> ［1929］ ……<strong class=\"source-bold\">ローマ教皇との和解</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> 教皇庁を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴァチカン市国</strong></span>として独立させ、国家として承認</p></blockquote>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">戦勝国なのに……領土問題は解決せず、国内も深刻な<ruby>不況<rt>ふきょう</rt></ruby>に！</strong></span></h3>\n<p><strong class=\"source-bold\">イタリア</strong>は<strong class=\"source-bold\">三国同盟（独・墺・伊）</strong>を結んでいたけど、大戦中の<strong class=\"source-bold\">ロンドン秘密条約</strong>で<strong class=\"source-bold\">「<ruby>未回収<rt>みかいしゅう</rt></ruby>のイタリア」の返還と引き換えに</strong>、<strong class=\"source-bold\">連合国側で参戦</strong>したよね。ってことは、イタリアは<strong class=\"source-bold\">戦勝国</strong>だ！ でも、領土問題が完全には解決しなかったんだよ。</p>\n<p>だって、英仏はドイツの弱体化しか考えていなかったから、イタリアのことには興味がない。一応、<strong class=\"source-bold\">トリエステ、イストリア、南チロルなど「未回収のイタリア」の多くは返還</strong>されたんだけど、<strong class=\"source-bold\">フィウメ</strong>やダルマチアは<strong class=\"source-bold\">ユーゴスラヴィア</strong>領となってしまい、獲得できなかった。これに怒った右翼の過激派ダヌンツィオが率いる軍人たちが、<strong class=\"source-bold\">フィウメを占領</strong>しちゃった！。でも、いくらなんでもやりすぎだな……。結局、<strong class=\"source-bold\">フィウメは国際連盟が管理する自由市</strong>になったんだけど、この事件の背景には、イタリアの政局をめぐる問題もあったんだよ。</p>\n<p>英仏はドイツから取った<ruby>賠償金<rt>ばいしょうきん</rt></ruby>で復興しようとしていたけど、<strong class=\"source-bold\">イタリアは賠償金をあまりもらえなかった</strong>んだ。さらに、戦争の被害で経済が悪化して（大戦前からたいして強くなかったけど……）、<strong class=\"source-bold\">戦後は深刻な不況</strong>になった。こうした経済混</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "284": "<h2>284</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第15回</strong></span> 戦間期の欧米諸国 〜世界恐慌以前〜</p>\n<p>乱から<strong class=\"source-bold\">社会主義が台頭</strong>し、なんと議会では<strong class=\"source-bold\">社会党が第1党</strong>になった！ さらに、社会党の左派は<strong class=\"source-bold\">イタリア共産党</strong>を結成して、もっと過激な運動を目指したんだ。そして、<strong class=\"source-bold\">社会主義者が指導するストライキ</strong>が、<strong class=\"source-bold\">北イタリア</strong>を中心に頻発したんだよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">反社会主義を唱えるムッソリーニが台頭。ファシズム政権ができた！</strong></span></h3>\n<p>こうした<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北イタリアのストライキ</strong></span>に対し、資本家は警戒感を強めていたんだ。だって、ストライキがどんどん過激になって、<strong class=\"source-bold\">工場占拠闘争</strong>に発展したんだもん。一方で、<strong class=\"source-bold\">反社会主義を唱える過激な保守派</strong>は、労働者や社会党の事務所、あるいはストライキを暴力的に攻撃して<ruby>潰<rt>つぶ</rt></ruby>す<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ファシズム運動</strong></span>を展開したんだ。なかでも、ストライキ破りで有名になり、資本家に支持されたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムッソリーニ</strong></span>だ。</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムッソリーニ</strong></span>は<strong class=\"source-bold\">もともと社会党員</strong>で、機関誌の編集長をしていたこともあるんだけど、戦争に反対していたはずの社会党の機関誌に「イタリアも参戦すべきである」という記事を載せたから、まんまと<strong class=\"source-bold\">党を除名された</strong>。まぁ、このあとの彼の行動を考えると、社会党にいたことのほうが気持ち悪いけど。こうして<strong class=\"source-bold\">ムッソリーニは反社会主義運動を始め</strong>、ミラノで復員兵士などとともに<strong class=\"source-bold\">「戦闘ファッシ（戦士のファッシ）」</strong>を結成すると、1921年には武力集団だった戦闘ファッシを政党に変えたんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ファシスト党</strong></span> <strong class=\"source-bold\">【</strong>国民ファシスト党<strong class=\"source-bold\">】</strong>だよ。政党になったとはいえ、党員全員が行動隊と呼ばれる武装組織のメンバーになったから、実態はあまり変わってないけどさ。そして、<strong class=\"source-bold\">労働者のストライキを武力で潰す</strong>直接行動を起こしながら勢力を拡大し、<strong class=\"source-bold\">ミラノやジェノヴァなどの都市を支配下</strong>に置いていったんだ。</p>\n<p>こうして、イタリア北部や中部で勢力を拡大した<strong class=\"source-bold\">ファシスト党は、国家権力を握るための行動を開始</strong>し、黒シャツに身を包んだ約2万人の<strong class=\"source-bold\">武装したファシスト</strong>（ガリバルディの赤シャツ隊をもじって<strong class=\"source-bold\">「黒シャツ隊」</strong>といわれることもある）が、一斉にローマに向かったんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローマ<ruby>進軍<rt>しんぐん</rt></ruby></strong></span>だ。</p>\n<blockquote><p>まさかガリバルディも、こんな連中にもじられるとは思ってなかっただろうな……</p></blockquote>\n<p>これを見た政府は、<ruby>戒厳令<rt>かいげんれい</rt></ruby>の発布を国王に頼んだんだけど、<strong class=\"source-bold\">国王は</strong>「社会党の影響力がある政府より、ムッソリーニのほうがマシだ」と言って<strong class=\"source-bold\"><ruby>鎮圧<rt>ちんあつ</rt></ruby>を拒否</strong>し、<strong class=\"source-bold\">ムッソリーニに内閣をつくるように命じた</strong>んだ。ここに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ムッソリーニ政権</strong></span>が誕生したよ。</p>",
  "285": "<h2>285</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">イタリア 〜ファシズム政権の出現〜</u></p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ファシスト党が一党<ruby>独裁<rt>どくさい</rt></ruby>体制を確立し、ムッソリーニの独裁が始まった！</strong></span></h3>\n<p>議会にわずか35議席（全体の6.5%）しか持たないムッソリーニ政権は、<strong class=\"source-bold\">社会主義に反対する資本家や地主など</strong>の自由主義勢力に支持されたんだけど、これって、たまたまこの時期に<strong class=\"source-bold\">イタリア経済が好況になった</strong>からなんだよ。だって、この時期はヨーロッパ全体の経済が良くなってきた時期でしょ。別にムッソリーニがすごかったわけじゃない。これが大きな間違いだったんだよ。</p>\n<p><strong class=\"source-bold\">ムッソリーニ</strong>は、全得票の25%を獲得した政党が3分の2の議席を獲得できるというよくわからん<strong class=\"source-bold\">新選挙法を制定すると、総選挙で勝利した</strong>。って、勝てるように選挙法を変えたんだから当たり前だよ。そして、「イタリア人はみんなファシストであることが望ましい」と言って、1926年に<strong class=\"source-bold\">ほかの政党を解散</strong>させて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">一党独裁体制</strong></span>を確立したよ。さらに、1928年には<strong class=\"source-bold\">ファシスト党の会議</strong>だったはずの<strong class=\"source-bold\">ファシズム大評議会</strong>を国家の最高議決機関にして、<strong class=\"source-bold\">独裁体制を完成させた</strong>んだ。</p>\n<h3><strong class=\"source-bold\">〈ムッソリーニの対外進出〉</strong></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-marker=\"outline-arrow\" data-source-color=\"red\" style=\"color:#e52715\">⇨</span> <span data-source-marker=\"point\" data-source-color=\"red\" style=\"color:#e52715\">●</span> フィウメ</td><td><strong class=\"source-bold\">ユーゴスラヴィア</strong></td></tr><tr><td><strong class=\"source-bold\">イタリア</strong></td><td><span data-source-marker=\"outline-arrow\" data-source-color=\"red\" style=\"color:#e52715\">⇨</span> <strong class=\"source-bold\">アルバニア</strong></td></tr><tr><td><span data-source-marker=\"point\" data-source-color=\"red\" style=\"color:#e52715\">●</span> ローマ</td><td></td></tr></tbody></table></div>\n<blockquote><p>ヴァチカン市国は、首都ローマのなかだよ。ムッソリーニの対外進出を地図で確認してね！</p></blockquote>\n<p>この間に、ムッソリーニは<strong class=\"source-bold\">対外進出</strong>を進めているよ。まず、第一次世界大戦後に獲得できなかった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フィウメ</strong></span>を、<strong class=\"source-bold\">ユーゴスラヴィア</strong>を<ruby>恐喝<rt>きょうかつ</rt></ruby>して強引に<ruby>併合<rt>へいごう</rt></ruby>すると、アドリア海を挟んだ対岸の小国<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルバニア</strong></span>に軍を送り、「キミみたいな小国は、いつ誰にやられるかわからないから、イタリアが保護してあげよう！」と、無理やり軍を送って<strong class=\"source-bold\">保護国にした</strong>んだ。ていうか、オマエが<ruby>侵略<rt>しんりゃく</rt></ruby>者だろ。</p>\n<p>ただ、<strong class=\"source-bold\">ムッソリーニ政権はそれなりに国民の支持を受けていた</strong>。それは、ムッソリーニがイタリア統一以来ずっと続いていた<strong class=\"source-bold\">「国家と教会の対立」を解消</strong>したからだよ。覚えてるかな？ イタリア統一の際に教皇領を併合したから、<strong class=\"source-bold\">ローマ教皇が</strong>スネちゃって<strong class=\"source-bold\">イタリア王国を承認せず</strong>、「ヴァチカンの<ruby>囚人<rt>しゅうじん</rt></ruby>」だ、って騒いでたでしょ。これを解決したのが、ムッソリーニが結んだ<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラテラノ条約</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラテラン条約</strong></span><strong class=\"source-bold\">】</strong>だよ。この条約では、<strong class=\"source-bold\">カトリックをイタリア唯一の宗教として承認</strong>すると、<ruby>教<rt>きょう</rt></ruby></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "286": "<h2>286</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第15回</strong></span> 戦間期の欧米諸国 〜世界恐慌以前〜</p>\n<p><ruby>皇庁<rt>こうちょう</rt></ruby>を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴァチカン市国</strong></span>として独立させて、<strong class=\"source-bold\">国家として承認</strong>したから、教皇ピウス11世もイタリアを承認したんだ。ちなみに、<strong class=\"source-bold\">ヴァチカン市国の広さはだいたい東京ディズニーランドと同じくらい</strong>。ローマ市のなかにある小さな国、でもこれって<strong class=\"source-bold\">教皇領の復活</strong>だよ。</p>\n<p>教皇と和解したことで、統一以来イタリア人を悩ませてきた<strong class=\"source-bold\">「国家と教会の対立」が解消した</strong>よ。イタリア人は、自己矛盾のような状態に終止符を打ったムッソリーニ政権を支持したんだよ。</p>\n<h2><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ソ連 〜社会主義国家の建設〜</strong></span></h2>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">クローズアップ</span> <strong class=\"source-bold\">革命後のロシア（ソ連）</strong></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">対ソ<ruby>干渉<rt>かんしょう</rt></ruby>戦争</strong></span> ［1918〜22］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">アメリカや日本が</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シベリア出兵</strong></span>をおこなう</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦時共産主義</strong></span> ［1918〜21］ ……<strong class=\"source-bold\">急激な社会主義化</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">穀物の強制徴発</strong>などを実施 <span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">経済<ruby>破綻<rt>はたん</rt></ruby>と食糧危機</strong>を招く</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">新経済政策</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネップ</strong></span><strong class=\"source-bold\">】</strong> ［1921］ ……<strong class=\"source-bold\">一部に資本主義を復活</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">穀物徴発の廃止</strong>など <span data-source-color=\"green\" style=\"color:#315837\">➡</span>民間の生産意欲が回復</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソヴィエト社会主義共和国連邦</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">U.S.S.R.</strong></span><strong class=\"source-bold\">】</strong> 成立 ［1922］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウクライナ</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベラルーシ</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">白ロシア</strong></span><strong class=\"source-bold\">】</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ザカフカース</strong></span>で成立</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニンの死</strong></span> ［1924］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トロツキー</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン</strong></span>が対立</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">スターリンが、トロツキーらを失脚させて</strong>権力を<ruby>掌握<rt>しょうあく</rt></ruby></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン<ruby>独裁<rt>どくさい</rt></ruby></strong></span></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次五カ年計画</strong></span> ［1928〜32］ ……再び<strong class=\"source-bold\">急激に社会主義化</strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">重工業優先の工業化と農業集団化</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">農業集団化</strong>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソフホーズ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国営農場</strong></span>）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コルホーズ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">集団農場</strong></span>）の建設</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次五カ年計画</strong></span> ［1933〜37］ <span data-source-color=\"green\" style=\"color:#315837\">➡</span>国際情勢から<strong class=\"source-bold\">重工業・軍事に重点</strong>が置かれた</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン憲法</strong></span> ［1936］</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> 外見的には民主的だが、<strong class=\"source-bold\">実際には市民的権利は保障されず</strong></p></blockquote>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">国内外での革命打倒の動き。白軍による反革命と対ソ干渉戦争</strong></span></h3>\n<p>続いて、<strong class=\"source-bold\">ロシア革命後のロシア（ソ連）</strong>について見ていこう。革命後のロシア国内では、<strong class=\"source-bold\">社会主義を<ruby>潰<rt>つぶ</rt></ruby>そうとする旧ロシア帝国軍などの反革命勢力</strong>（これを<strong class=\"source-bold\">白軍</strong>って呼んでるよ）との<strong class=\"source-bold\">内戦</strong>が起きて、ソヴィエト政権を大きく揺るがし、さらに<strong class=\"source-bold\">連合国も社会主義の拡大を警戒して出兵</strong>してきたんだ。</p>",
  "287": "<h2>287</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ソ連 〜社会主義国家の建設〜</u></p>\n<p>この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">対ソ干渉戦争</strong></span>では、<strong class=\"source-bold\">イギリスやフランス</strong>がフィンランド国境に近いムルマンスクに上陸して北からペトログラードなどを脅かし、東では<strong class=\"source-bold\">チェコ兵<ruby>捕虜<rt>ほりょ</rt></ruby>の救出</strong>を口実に<strong class=\"source-bold\">日本やアメリカ</strong>などが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シベリア出兵</strong></span>をおこなった。さらに、<strong class=\"source-bold\">ポーランド</strong>が、ポーランド分割で失った領土を取り返そうと攻めてきたんだ（<strong class=\"source-bold\">ソヴィエト＝ポーランド戦争</strong>）。</p>\n<p>こうした各国軍の侵入に対し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トロツキー</strong></span>はソヴィエト政権の軍隊として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>赤軍<rt>せきぐん</rt></ruby></strong></span>を結成して戦ったよ。さらに後進国<strong class=\"source-bold\">ロシアでの社会主義革命を守るため</strong>には、ドイツやポーランドなど、ロシアを取り囲む国でも同時に革命を起こさなきゃいけない！ この<strong class=\"source-bold\">「世界革命」</strong>のために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コミンテルン</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第3インターナショナル</strong></span>・共産主義インターナショナル<strong class=\"source-bold\">】</strong>が結成された。これは、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア共産党</strong></span>の指導のもとに、<strong class=\"source-bold\">世界各地の共産勢力を結集</strong>するための組織だ。さらに、<strong class=\"source-bold\">国内の反革命を取り締まるための秘密警察組織</strong>（国内スパイだ！）である<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェカ</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">非常委員会</strong></span><strong class=\"source-bold\">】</strong>が設置されたよ。</p>\n<p>しかし、国土が戦場となったために<strong class=\"source-bold\">食糧が不足</strong>し、<strong class=\"source-bold\">工業生産力も低下</strong>しちゃった。このため<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニン</strong></span>は、「すべてを戦線へ！」として、<strong class=\"source-bold\">あらゆる物資を戦争に動員</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦時共産主義</strong></span>を導入したよ。まず、中小工場なども含めた<strong class=\"source-bold\">私企業をすべて国有化</strong>し、労働者や兵士の食糧を確保するために農民からは<strong class=\"source-bold\">穀物を強制徴発</strong>（無理やり全部取り上げる）した。さらに燃料確保（まだ<ruby>薪<rt>まき</rt></ruby>が中心……）のため農民に労役を課すなど、<strong class=\"source-bold\">戦争の負担を全部農民に押しつけた</strong>んだよ。しかも<strong class=\"source-bold\">食糧が配給制</strong>になったから、農民は日々の食糧にも困った。そして戦時共産主義は、この時期に急増した共産党員を使って進められたから、<strong class=\"source-bold\">共産党の一党独裁体制が強化された</strong>んだよ。</p>\n<blockquote><p>第一次大戦が終わったのに、戦時共産主義で、人びとの生活は全然よくならなかったよ</p></blockquote>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">戦時共産主義の導入で経済が破綻！ 再建のためにネップが採用された</strong></span></h3>\n<p>戦時共産主義の導入で<strong class=\"source-bold\">農民はすっかりやる気をなくした</strong>。だって、何をつくっても国に取られちゃうから、<ruby>頑張<rt>がんば</rt></ruby>って穀物を生産しても意味がない……。不満を爆発させた中央アジアの農民が反乱を起こすと、<strong class=\"source-bold\">農民反乱は全国に拡大</strong>したんだ。そして、農民反乱に加えて大寒波に襲われたロシアでは、1920年に入って<strong class=\"source-bold\">食糧危機</strong>が起こり、都市労働者や兵士の間でも不満が高まり、ついに<strong class=\"source-bold\">軍の内部でも反乱が起きた</strong>（クロンシュタット<ruby>要塞<rt>ようさい</rt></ruby>の水兵反乱）。</p>\n<p>ただ、1920年ごろには<strong class=\"source-bold\">対ソ干渉戦争がほぼ終結</strong>したよ。<strong class=\"source-bold\">英・仏・米は1920年に撤兵</strong>し（日本は1922年まで出兵を続けたけど）、<strong class=\"source-bold\">国内の反革命勢力もほとんど制圧</strong>したから、「革命を守るめどが立ったな……」と判断した<strong class=\"source-bold\">レーニンは政策を転換</strong>したんだ。</p>\n<p>こうして1921年の春には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">新経済政策</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネップ</strong></span><strong class=\"source-bold\">】</strong>が採用されたよ。まず、<strong class=\"source-bold\">穀物の強制徴発をやめて</strong>、税を納めたあとに余った穀物は自由に売ってもいいことにした。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "288": "<h2>288</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第15回</strong></span> 戦間期の欧米諸国 〜世界恐慌以前〜</p>\n<p>町工場や商店など<strong class=\"source-bold\">小規模な企業の営業を認め</strong>、大企業や銀行などの重要産業も国有のままとはいえ、独立採算制にしたんだ。これって、「みんながやる気を取り戻すように」、<strong class=\"source-bold\">一定の範囲内で資本主義や市場経済を復活</strong>したんだ。だから、ネップによって国内経済は少しずつ回復に向かい、農民のなかからは<strong class=\"source-bold\">クラーク</strong>（富農）が現れ、商工業でも<strong class=\"source-bold\">ネップマン</strong>（商工業で金持ちになった人）も出現したよ。</p>\n<blockquote><p>ネップでやる気になった人たちは豊かになったんだけど……あとでひどい目にあうよ</p></blockquote>\n<p>そして、<strong class=\"source-bold\">各国も</strong>ネップを見て「ソヴィエト政権は、そこまで危険でもないかもしれない……」と思い、少しずつ<strong class=\"source-bold\">ソヴィエト政権との関係を探り始めた</strong>んだ。1921年にはイギリスが経済<ruby>封鎖<rt>ふうさ</rt></ruby>を解除して<strong class=\"source-bold\">英ソ通商協定</strong>を結び、1922年には<strong class=\"source-bold\">ドイツ</strong>もソヴィエト政権（ソ連）と国交を回復する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ラパロ条約</strong></span>を結んだよ。同年末にソ連が成立したあと、1924年には<strong class=\"source-bold\">イギリス、イタリア、フランス</strong>が、1925年には日本が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連を承認</strong></span>したんだけど、<strong class=\"source-bold\">アメリカはなかなか承認しなかった</strong>んだ。アメリカが承認するのは、世界<ruby>恐慌<rt>きょうこう</rt></ruby>のあとだよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ロシアを中心とする4共和国で、ソ連が成立した！</strong></span></h3>\n<p>ロシアの経済が回復に向かい始めたころ、かつてのロシア帝国領内では<strong class=\"source-bold\">ロシア以外に3つのソヴィエト共和国が樹立された</strong>よ。そして、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウクライナ</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベラルーシ</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">白ロシア</strong></span><strong class=\"source-bold\">】</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ザカフカース</strong></span>の4ソヴィエト共和国は、1922年の全連邦ソヴィエト第1回大会で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソヴィエト社会主義共和国連邦</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">U.S.S.R.</strong></span><strong class=\"source-bold\">】</strong>を結成し、1924年には<strong class=\"source-bold\">ソヴィエト社会主義憲法</strong>を制定したんだ。</p>\n<p>そして、この4共和国以外の<strong class=\"source-bold\">旧ロシア帝国領もソ連に<ruby>併合<rt>へいごう</rt></ruby>されていった</strong>。まず、<strong class=\"source-bold\">ムスリムの知識人が自治や改革を求める運動（ジャディード運動）をやっていた中央アジア</strong>は、1924年には<strong class=\"source-bold\">ウズベク・カザフ・キルギス・タジク・トルクメン</strong>共和国に分割されて、その後、無理やりソ連に併合されちゃったんだ。そして、1936年にはザカフカースが<strong class=\"source-bold\">グルジア</strong>（現ジョージア）・<strong class=\"source-bold\">アルメニア</strong>・<strong class=\"source-bold\">アゼルバイジャン</strong>に分離されて、最終的に<strong class=\"source-bold\">ソ連は15共和国で構成される連邦国家</strong>になった。とはいっても各共和国に自由や自治などはなく、<strong class=\"source-bold\">完全に</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア共産党</strong></span>（1952年から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連共産党</strong></span>）<strong class=\"source-bold\">の支配下に置かれた</strong>んだ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">レーニンが死ぬと、スターリンの<ruby>独裁<rt>どくさい</rt></ruby>が始まった！</strong></span></h3>\n<p>ネップによって国内がやっと安定してきたソ連だったけど、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニンの死</strong></span>後、<strong class=\"source-bold\">共産党内部での対立が表面化</strong>したよ。もともと有力な後継者だと思われていたのは、伝統的な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界革命論</strong></span>（ヨーロッパで社会主義革命が起こるまで、ソ連が持ちこたえる）を主張する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トロツキー</strong></span>だったんだけど、レーニンが病気で倒れたあとに共産党</p>",
  "289": "<h2>289</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">5</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ソ連 〜社会主義国家の建設〜</u></p>\n<p>書記長となった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン</strong></span>は、「世界革命論は古くさい！ <strong class=\"source-bold\">ソ連のような後進国1国でも、社会主義は実現できる</strong>」という<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">一国社会主義論</strong></span>を唱えて、トロツキーと対立したんだ。これって、<strong class=\"source-bold\">トロツキーを孤立させる</strong>作戦だよ。</p>\n<blockquote><p>レーニンはスターリンの危ない面を見抜いて、「スターリンを後継者にしちゃいけない」って遺言したけど、もみ消されたんだよ……</p></blockquote>\n<p>スターリンのやり方は巧妙だよ。まず、自分以外で一番有力な人物を孤立させるために、指導部のほかの連中を味方につける。そして、影響力を弱めたところで、今度は手を組んだ連中のなかで有力なヤツを<ruby>潰<rt>つぶ</rt></ruby>す。これを繰り返したんだよ。最初の標的<strong class=\"source-bold\">トロツキーを倒す</strong>ためにジェノヴィエフやカーメネフと組み、弱らせたところで、今度は<strong class=\"source-bold\">ジェノヴィエフを倒す</strong>ためにブハーリンと組む。そして最後は<strong class=\"source-bold\">ブハーリンも潰す</strong>。結局、<strong class=\"source-bold\">スターリンは党内の有力者をほとんど失脚させた</strong>！。</p>\n<p><strong class=\"source-bold\">失脚したトロツキー</strong>はのちに<strong class=\"source-bold\">国外追放</strong>となり、さらに<strong class=\"source-bold\">メキシコで暗殺</strong>された。ジェノヴィエフもカーメネフもブハーリンも、次々と失脚して処刑されたんだもん。こうして反対派を次々と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>粛清<rt>しゅくせい</rt></ruby></strong></span>して、<strong class=\"source-bold\">スターリンは独裁体制を確立</strong>したんだ（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン体制</strong></span>）。スターリンの大粛清で<strong class=\"source-bold\">逮捕された人は約1200万人</strong>。そのうち<strong class=\"source-bold\">100万人が処刑</strong>され、200万人は収容所で死亡したんだよ。なんて時代だよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">五カ年計画が実施され、急激な社会主義化が始まる！</strong></span></h3>\n<p>同じころ、<strong class=\"source-bold\">スターリンはネップに対する警戒感を強めていた</strong>んだ。農村では「自分が食べる分は絶対取っとかなきゃ！」って思った農民が穀物を売り惜しみ、食糧不足を見た商人は穀物を買い占めた。だから、<strong class=\"source-bold\">都市や軍の内部では穀物不足</strong>が起きていたよ。工業の基盤が弱いソ連は、<strong class=\"source-bold\">工業発展の資金を穀物輸出に頼る</strong>しかない。じゃあどうするか？って、んなもん農民から取り上げるしかないじゃん。</p>\n<p>1928年、スターリンは<strong class=\"source-bold\">工業国への転換</strong>を掲げる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次五カ年計画</strong></span>を始めたよ。この計画に基づいて<strong class=\"source-bold\">重工業優先の工業化</strong>を進め、その資金を農民から搾り取るために<strong class=\"source-bold\">急激な農業の集団化</strong>を進めた。農村では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソフホーズ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国営農場</strong></span>）や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コルホーズ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">集団農場</strong></span>）が無理やり建設され、<strong class=\"source-bold\">農民は穀物を国に奪い取られた</strong>。反対する農民は「社会主義の敵、クラークだ」というレッテルを貼って次々と逮捕し、<strong class=\"source-bold\">シベリアや極北に追放</strong>して鉱山などで強制労働させた。反対するヤツは、みんなシベリア送りだよ……！。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "290": "<h2>290</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第15回</strong></span> 戦間期の欧米諸国 〜世界恐慌以前〜</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">合</span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">否</span><strong class=\"source-bold\">の分かれ目</strong> <strong class=\"source-bold\">ソ連の経済政策の変化に注目！</strong></h3>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦時共産主義</strong></span> ［1918〜21］ （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニン</strong></span>） ……<strong class=\"source-bold\">急激な<u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\">社会主義化</u></strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">穀物の強制徴発、私企業の一切禁止</strong></p>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">新経済政策</strong></span> <strong class=\"source-bold\">【</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ネップ</strong></span><strong class=\"source-bold\">】</strong> ［1921］ （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニン</strong></span>） ……<strong class=\"source-bold\">一部に<u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\">資本主義を復活</u></strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">穀物徴発の廃止、小農経営、小規模な私企業</strong>の営業を認める</p>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次五カ年計画</strong></span>［1928〜32］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン</strong></span>）……再び<strong class=\"source-bold\">急激に<u data-source-underline-color=\"gray\" data-source-underline-style=\"double\" style=\"text-decoration-color:#777777;text-decoration-style:double\">社会主義化</u></strong></p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span> <strong class=\"source-bold\">重工業優先の工業化と農業集団化</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソフホーズ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国営農場</strong></span>）、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コルホーズ</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">集団農場</strong></span>）の建設</p></blockquote>\n<p>そして同じころ、資本主義諸国では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界<ruby>恐慌<rt>きょうこう</rt></ruby></strong></span>が起きた。この時スターリンは、「<strong class=\"source-bold\">ソ連は恐慌の影響を受けずに発展している</strong>。まさに社会主義の勝利だ！」って大宣伝したんだよ。でも実際には、<strong class=\"source-bold\">急激な農業集団化で農民が完全にやる気をなくし</strong>、穀物の収穫は激減し、家畜の頭数も半減するなど<strong class=\"source-bold\">深刻な経済危機</strong>になった。この時期には400万人以上が<ruby>餓死<rt>がし</rt></ruby>したっていわれているよ。それに、世界恐慌の影響を受けなかったように見えるのは、<strong class=\"source-bold\">アメリカと国交のないソ連</strong>が、アメリカの<ruby>不況<rt>ふきょう</rt></ruby>の影響を受けなかっただけだし、<strong class=\"source-bold\">強制労働が経済成長を支えていた</strong>だけだからね。大恐慌に苦しむ各国が、<strong class=\"source-bold\">見た目の工業発展にダマされていた</strong>だけだよ。</p>\n<blockquote><p>世界恐慌に苦しむ人たちは、ソ連の見た目の発展に完全にダマされたんだよ</p></blockquote>\n<p>こうして完全に権力を握ったスターリンは、1936年に<strong class=\"source-bold\">新しい憲法を制定</strong>したよ（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン憲法</strong></span>）。平等や<ruby>飢<rt>う</rt></ruby>えからの解放など書いてあることは素晴らしいけど、<strong class=\"source-bold\">本人が守る気ゼロ</strong>。市民の権利を守ろうなんて、これっぽっちも考えてなかったからね。さらに、1933年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次五カ年計画</strong></span>が始まり、最初は国民の生活を良くするために<strong class=\"source-bold\">消費財部門にも配慮</strong>するとか言ってたのに、結局は<strong class=\"source-bold\">重工業・軍事中心に変わっちゃった</strong>。しかも、同じころにドイツでヒトラーが軍備拡大を進めていたから、<strong class=\"source-bold\">第3次五カ年計画</strong>は軍需産業ばっか。うーん、結局はスターリンの思い通りの政策しかできないってことだ。まぁ、それが<ruby>独裁<rt>どくさい</rt></ruby>体制だけどさ。</p>\n<h2><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">6</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">戦間期の東欧諸国</strong></span></h2>\n<p>最後に、難関大を狙う人のための<strong class=\"source-bold\">戦間期の東欧諸国</strong>のポイントだよ！</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハンガリー</strong></span>では、<strong class=\"source-bold\">クン＝ベラ</strong>を中心とする<strong class=\"source-bold\">ハンガリー革命</strong>が成功して、1919年に</p>",
  "291": "<h2>291</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">6</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦間期の東欧諸国</u></p>\n<p>社会主義政権を樹立したんだけど、<strong class=\"source-bold\">ルーマニア軍の侵入で倒されてしまった</strong>んだ。その後、軍人の<strong class=\"source-bold\">ホルティ</strong>が率いる反革命軍が実権を握ると、彼は「かつてのオーストリア＝ハンガリー帝国の栄光を復活する！」って言ってハプスブルク家を国王とみなし、「国王なき王政」の<ruby>摂政<rt>せっしょう</rt></ruby>として<strong class=\"source-bold\">独裁権を握った</strong>んだ。もちろんハプスブルク家がハンガリー王になったわけじゃないけどさ。そして、かつての領土を復活するために、<strong class=\"source-bold\">ルーマニア、チェコスロヴァキア、ユーゴスラヴィアからの領土奪還を狙った</strong>んだ。</p>\n<p>ホルティに「領土を取り返す！」と名指しされた<strong class=\"source-bold\">チェコスロヴァキア・ユーゴスラヴィア・ルーマニア</strong>の3国は連携して、<strong class=\"source-bold\">小協商</strong>を結んで対抗したよ。</p>\n<p>続いて、独立した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーランド</strong></span>では、<strong class=\"source-bold\">ピウスツキ</strong>が国家元首として<strong class=\"source-bold\">ソヴィエト＝ポーランド戦争</strong>などを戦い、ロシア（ソ連）から領土を奪い返した！ これまでの<ruby>恨<rt>うら</rt></ruby>みを晴らしたね。<strong class=\"source-bold\">ピウスツキ</strong>は一時辞任していたけど、クーデタで政権に復帰して、最終的には独裁体制となった。ていうか、東欧って独裁国家ばっかり……。</p>\n<p>といいつつ、まともな国もあったよ。大戦後にオーストリアから独立した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チェコスロヴァキア</strong></span>は、初代大統領の<strong class=\"source-bold\">マサリク</strong>を中心に<strong class=\"source-bold\">西欧型の議会制民主主義を確立</strong>して、さらに<strong class=\"source-bold\">工業発展</strong>にも努めたから、<strong class=\"source-bold\">イタリアより強くなった</strong>！ 「イタリアかよ……」って思っちゃダメよ。とにかく、入試ではチェコスロヴァキアが東欧で唯一<strong class=\"source-bold\">「議会制民主主義の確立」</strong>と<strong class=\"source-bold\">「工業化」</strong>に成功した国だ！っておさえておこう。この路線は、次の大統領<strong class=\"source-bold\">ベネシュ</strong>にも受け継がれたんだけど、<strong class=\"source-bold\">ヒトラーの<ruby>侵略<rt>しんりゃく</rt></ruby>を受けたのが、ベネシュ大統領の時代</strong>なんだよね。</p>\n<p>これで、戦間期の欧米諸国はおしまい。最後に年号checkしよう！</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">!!</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">年号のツボ</span></h3>\n<blockquote><p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span> <strong class=\"source-bold\">ワイマール憲法（独）</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1919</strong></span>］ （みんなで <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby></strong></span> 普通選挙）</p>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span> <strong class=\"source-bold\">ソ連の成立</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1922</strong></span>］ （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>い<rt>1</rt></ruby>ー<ruby>国<rt>92</rt></ruby><ruby>に<rt>2</rt></ruby></strong></span>なる ソヴィエト連邦）</p>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span> <strong class=\"source-bold\">ローマ<ruby>進軍<rt>しんぐん</rt></ruby>（伊）</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1922</strong></span>］ （ファシストは <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>い<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>つ<rt>2</rt></ruby><ruby>に<rt>2</rt></ruby></strong></span>なっても 権力ほしい）</p>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span> <strong class=\"source-bold\">ミュンヘン<ruby>一揆<rt>いっき</rt></ruby>（独）</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1923</strong></span>］ （<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>とっ<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>に<rt>2</rt></ruby><ruby>冷<rt>3</rt></ruby></strong></span>めた ナチスの熱狂）</p>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span> <strong class=\"source-bold\">移民法（米）</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1924</strong></span>］ （<ruby>WASP<rt>ワスプ</rt></ruby>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>苦<rt>9</rt></ruby><ruby>に<rt>2</rt></ruby><ruby>し<rt>4</rt></ruby></strong></span>た 移民流入）</p>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span> <strong class=\"source-bold\">第1次マクドナルド内閣（英）</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1924</strong></span>］ （政策が <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>特<rt>19</rt></ruby><ruby>に<rt>2</rt></ruby><ruby>よ<rt>4</rt></ruby></strong></span>くばり 労働党）</p>\n<p><span data-source-color=\"brown\" style=\"color:#a43725\">●</span> <strong class=\"source-bold\">第1次五カ年計画（ソ連）</strong> ［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">928</strong></span>］ （農村で <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>急<rt>9</rt></ruby><ruby>に<rt>2</rt></ruby><ruby>や<rt>8</rt></ruby></strong></span>るのか 集団化）</p></blockquote>\n<p>次回は、<strong class=\"source-bold\">戦間期のアジア</strong>だよ。第一次世界大戦後のインドや東南アジアでは、独立運動が盛り上がるよ！ 彼らに負けないように、<ruby>頑張<rt>がんば</rt></ruby>ろう〜。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦間期と第二次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "292": "<h2>292</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第15回</strong></span> 戦間期の欧米諸国 〜世界恐慌以前〜</p>\n<h2><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">近現代日本へのアプローチ</strong></span> <span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">6</span></h2>\n<h3><strong class=\"source-bold\">〜戦間期の経済・財政政策〜</strong></h3>\n<p>日本は、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>金本位制<rt>きんほんいせい</rt></ruby>を採用</strong></span> ［1897］してから<strong class=\"source-bold\">外国資本の導入</strong>を進めたんだけど、<ruby>日露<rt>にちろ</rt></ruby>戦争以来、<strong class=\"source-bold\">外国債</strong>（外国からの借金）が一気に増えたんだ（1903年に1億円→1913年に17億円）。しかも、重工業製品の輸入が増えて、<strong class=\"source-bold\">貿易も赤字</strong>だったから、第一次世界大戦直前の日本は国際収支が危機的状況だった。</p>\n<p>でも、第一次世界大戦が始まると、<strong class=\"source-bold\">連合国への軍事物資やアジアへの軽工業製品の輸出が大幅に増えて</strong>、しかも世界的な船舶不足から海運業や造船業が空前の好景気になって、<strong class=\"source-bold\">「<ruby>成金<rt>なりきん</rt></ruby>」</strong>（船成金）を生み出した。暗い玄関先で百円札（現在の約12万円）を燃やしてる絵を見たことないかな？ こうして日本は、<strong class=\"source-bold\">国際収支が大幅に黒字</strong>になり、アメリカと同じように<strong class=\"source-bold\"><ruby>債務<rt>さいむ</rt></ruby>国から<ruby>債権<rt>さいけん</rt></ruby>国になった</strong>よ。ただ、この<strong class=\"source-bold\">大戦景気</strong>で物価が上がって、民衆の生活は苦しくなったんだ。</p>\n<p>でもね、第一次世界大戦が終わってヨーロッパの復興が始まると、<strong class=\"source-bold\">日本は貿易赤字に逆戻り</strong>……。1920年には<strong class=\"source-bold\">戦後<ruby>恐慌<rt>きょうこう</rt></ruby></strong>になって株価だけじゃなく、綿糸や<ruby>生糸<rt>きいと</rt></ruby>の相場も大暴落したんだ。しかも悪いことは重なるんだよ。1923年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">関東大震災</strong></span>で首都圏全域、特に京浜工業地帯が壊滅して、輸出も激減した。政府はなんとか<ruby>復興<rt>ふっこう</rt></ruby>を進めようと、<strong class=\"source-bold\">震災手形（簡単に言うと被災者の借金）の取り立てを一時<ruby>猶予<rt>ゆうよ</rt></ruby>したんだ</strong>（<strong class=\"source-bold\">支払猶予令【モラトリアム】</strong>）。でも、震災手形の債務者（お金を借りている会社など）のなかには、すでに戦後恐慌で<ruby>潰<rt>つぶ</rt></ruby>れそうになっていた会社も含まれていて、いくら猶予したところで返済できない債務がたくさんあって、これが不良債権になってしまったんだ。</p>\n<p>1927年、<strong class=\"source-bold\">不良債権になった震災手形の取り付け騒ぎ</strong>が起こると、全国的に銀行が相次いで休業する事態になった（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">金融恐慌</strong></span>）。<ruby>田中義一<rt>たなかぎいち</rt></ruby>内閣は、再び支払猶予令を出して、公的資金の投入で恐慌を<ruby>鎮<rt>しず</rt></ruby>めたんだけど、震災復興のための輸入が多く、また日本の工業は国際的な競争力がなかったから、<strong class=\"source-bold\">貿易赤字は全然解消できなかった</strong>。これは、第一次世界大戦中から<strong class=\"source-bold\">金輸出の禁止</strong>（金本位制からの離脱）が続いて、インフレが起きていたことも原因だよ。</p>\n<p>そして1929年に成立した<ruby>浜口雄幸<rt>はまぐちおさち</rt></ruby>内閣の大蔵大臣（今の財務大臣）となった<ruby>井<rt>いの</rt></ruby><ruby>上準之助<rt>うえじゅんのすけ</rt></ruby>が、貿易収支の改善と<ruby>為替<rt>かわせ</rt></ruby>相場の安定、さらに欧米諸国と対等な地位を維持するために、1930年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">金輸出の解禁</strong></span>（金本位制への復帰）に踏み切って、さらに<strong class=\"source-bold\">緊縮財政</strong>（赤字を減らすために政府の支出を少なくすること）<strong class=\"source-bold\">を進めた</strong>（<strong class=\"source-bold\">井上財政</strong>）。でも、1929年って<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界恐慌</strong></span>が起きた年だよね。<strong class=\"source-bold\">金輸出解禁で円高</strong>になったことで、<strong class=\"source-bold\">日本は輸出が打撃を受け、世界恐慌の波及</strong>とあわせて、深刻な経済危機に陥ってしまったんだ（<strong class=\"source-bold\">昭和恐慌</strong>）。</p>"
};

